// 🔧 Configuración
const diasABuscar = 7;        // cantidad de días hacia adelante
const horaInicio = 9;         // hora de inicio (ej: 9 AM)
const horaFin = 17;           // hora de fin (ej: 18 hs)
const duracionSlot = 30;      // duración de cada slot en minutos
const espacioEntreSlots = 0;  // minutos de espacio entre slots

// Función para convertir a hora de Mendoza (UTC-3)
function toMendozaDate(dateTimeStr) {
  const date = new Date(dateTimeStr);
  // Ajustar manualmente a UTC-3
  const utc = date.getTime() + (date.getTimezoneOffset() * 60000);
  return new Date(utc - (3 * 60 * 60000));
}

// Obtener los eventos normalizados
const eventos = items.map(item => {
  const inicio = toMendozaDate(item.json.start.dateTime);
  const fin = toMendozaDate(item.json.end.dateTime);
  return { inicio, fin };
});

// Verifica si un slot se cruza con algún evento ocupado
function estaDisponible(inicioSlot, finSlot, eventos) {
  for (const ev of eventos) {
    if (inicioSlot < ev.fin && finSlot > ev.inicio) {
      return false;
    }
  }
  return true;
}

// Generar slots por día
const resultados = [];
const ahora = new Date();
ahora.setHours(0, 0, 0, 0); // reset hora actual

for (let d = 0; d < diasABuscar; d++) {
  const fechaBase = new Date(ahora);
  fechaBase.setDate(fechaBase.getDate() + d);

  let cursor = new Date(fechaBase);
  cursor.setHours(horaInicio, 0, 0, 0);

  const finDia = new Date(fechaBase);
  finDia.setHours(horaFin, 0, 0, 0);

  while (cursor.getTime() + duracionSlot * 60000 <= finDia.getTime()) {
    const inicioSlot = new Date(cursor);
    const finSlot = new Date(cursor.getTime() + duracionSlot * 60000);

    if (estaDisponible(inicioSlot, finSlot, eventos)) {
      resultados.push({
        fecha: inicioSlot.toISOString().split('T')[0],
        desde: inicioSlot.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' }),
        hasta: finSlot.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' }),
        isoInicio: inicioSlot.toISOString(),
        isoFin: finSlot.toISOString()
      });
    }

    cursor = new Date(cursor.getTime() + (duracionSlot + espacioEntreSlots) * 60000);
  }
}

// Agrupar todos los resultados en un solo objeto
return [
  {
    json: {
      disponibilidad: resultados
    }
  }
];

